---@class UIFishPoolCreelDialog
local UIFishPoolCreelDialog = Class("UIFishPoolCreelDialog")

function UIFishPoolCreelDialog:__init() 
    self._allFishData = {}            --所有的鱼
    self._curSelectInd = 1            --当前选择的下标

    self._curSelectType = 1           --当前的选择类型
    self._selectBatchIds = {}             --选中的数据
end

function UIFishPoolCreelDialog:__delete()
    self._allFishData = nil            --所有的鱼
    self._curSelectInd = nil            --当前选择的下标
    self._curSelectType = nil           --当前的选择类型
    self._selectBatchIds = nil            --选中的数据
end

function UIFishPoolCreelDialog:Awake()
    self.EventFishBasketChange = Events.AddListener(Constants.EventNames.FishBasketChange, Bind(self, self.OnFishBasketChange))

    SetButtonAction(self.FontStyleButton2, Bind(self, self.OnBatchSell))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBatchMake))
    SetButtonAction(self.BtnSelectAll, Bind(self, self.OnBtnSelectAll))

    self:InitData()

    self:FillSortsInfo()
    self:FillSelf()
end

function UIFishPoolCreelDialog:FillSortsInfo()
    if not self._isInitSortInfo then
        SetButtonAction(self.BtnAlign, Bind(self, self.OnBtnRefreshBtnAlign))
        SetButtonAction(self.BtnAlign2, Bind(self, self.OnBtnRefreshBtnAlign2))

        for k, v in pairs(SortType) do
            local go = CfUtils.InstantiateGo(self.AlignCell, self.DropDown)
            go.name = "sort"..k
            self:FillSortInfo(go, v)
            SetButtonAction(go.transform:Find("Toggle"), function()
                self._curSelectInd = 1
                self._curSortRareData = v
                self:FillSortInfo(self.BtnAlign, self._curSortRareData)
                self:OnBtnRefreshBtnAlign()
                self:RefreshLoopList()
            end)

            KTool.SetActive(go, true)

            if k == 1 then
                self._curSortRareData = v
                self:FillSortInfo(self.BtnAlign, self._curSortRareData)
                --CfUtils.FillText(self.BtnAlign.transform:Find("CellButton/Text"), localize("默认"))
                --KTool.SetActive(self.BtnAlign.transform:Find("CellButton/Image"), false)
            end
        end

        self._allFishPlace = FishingUtils.GetAllFishPlace()
        table.insert(self._allFishPlace, 1, {
            id = 0,
            name = localize("全部")
        })

        CfUtils.FillText(self.BtnAlign2:Find("CellButton/Text"), localize("渔场"))
        for k, v in pairs(self._allFishPlace) do
            local go = CfUtils.InstantiateGo(self.AlignCell2, self.DropDown2)
            go.name = "sort"..k
            CfUtils.FillText(go.transform:Find("CellButton/Text"), v.name)

            SetButtonAction(go.transform:Find("Toggle"), function()
                self._curSelectInd = 1
                self._curPlaceData = v
                CfUtils.FillText(self.BtnAlign2:Find("CellButton/Text"), self._curPlaceData.name)
                self:OnBtnRefreshBtnAlign2()
                self:RefreshLoopList()

                if self._curSelectType == SelectType.Batch then
                    --self._isSelectAll = false
                    self:FillBtnSelectAll(true)
                end
            end)
            KTool.SetActive(go, true)

            if checkNumber(self._curFishPlaceId) == checkNumber(v.id) then
                self._curPlaceData = v
                CfUtils.FillText(self.BtnAlign2:Find("CellButton/Text"), self._curPlaceData.name)
            end
        end
    end
end

function UIFishPoolCreelDialog:FillSortInfo(go ,data)
    if not go or not data then
        return
    end
    CfUtils.FillText(go.transform:Find("CellButton/Text"), data.name)
    if data.id ~= 0 then
        KTool.SetActive(go.transform:Find("CellButton/Image"), true)
        --go.transform:Find("CellButton/Image").localRotation = Quaternion.Euler(0, 0, checkNumber(data.rot))
    else
        KTool.SetActive(go.transform:Find("CellButton/Image"), false)
    end
end

function UIFishPoolCreelDialog:OnBtnRefreshBtnAlign()
    self._isShowRareSortType = not checkBool(self._isShowRareSortType)
    KTool.SetActive(self.DropDown, self._isShowRareSortType)
end

function UIFishPoolCreelDialog:OnBtnRefreshBtnAlign2()
    self._isShowPlaceSortType = not checkBool(self._isShowPlaceSortType)
    KTool.SetActive(self.DropDown2, self._isShowPlaceSortType)
end


--初始化数据
function UIFishPoolCreelDialog:InitData()
    self._allFishDojoData = {}         
    local t = fishingComponent:GetAllFishData()
    if not t then 
        return
    end

    for k, v in pairs(t) do
        table.insert(self._allFishDojoData, v)
    end
end

function UIFishPoolCreelDialog:FillSelf()
    local isHaveFish = #self._allFishDojoData > 0
    KTool.SetActive(self.Content, isHaveFish)
    KTool.SetActive(self.Empty, not isHaveFish)

    KTool.SetActive(self.BatchProductionPanel, false)

    self:RefreshLoopList()
    KTool.SetActive(self.ChooseNumberPanel, #self._allFishData > 0)
end

--刷新当前选择的信息
function UIFishPoolCreelDialog:RefreshCurSelectItemInd(selectInd)
    selectInd = checkNumber(selectInd)
    local go
    if checkNumber(self._curSelectInd) > 0 then
        go = self.LoopList:GetShownItemByItemIndex(checkNumber(self._curSelectInd) - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIFishPoolCreelItemNode)
            if lastScr then
                lastScr:RefreshSelectActive(false)
            end
        end
    end
    self._curSelectInd = selectInd
    if checkNumber(self._curSelectInd) > 0 then
        go = self.LoopList:GetShownItemByItemIndex(checkNumber(self._curSelectInd) - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIFishPoolCreelItemNode)
            if lastScr then
                lastScr:RefreshSelectActive(true)
            end
        end
    end
    self:RefreshCurSelectItemInfo()
end

--刷新当前选择的信息
function UIFishPoolCreelDialog:RefreshCurSelectItemInfo()
    local scr = CfUtils.GetLuaScr(self.ChooseNumberPanel, UIFishPoolCreelSelectNode)
    if scr then
        scr:Refresh(self._allFishData[self._curSelectInd])
    end
end

--刷新批量信息
function UIFishPoolCreelDialog:RefreshCurBatchInfo(type)
    self._curBatchType = type
    self:RefreshLoopList()
    local scr = CfUtils.GetLuaScr(self.BatchProductionPanel, UIFishPoolCreelBatchNode)
    if scr then
        scr:Refresh(type, self._selectBatchIds, function()
            self._curSelectType = SelectType.Single
            KTool.SetActive(self.ChooseNumberPanel, #self._allFishDojoData > 0)
            KTool.SetActive(self.BatchProductionPanel, false)

            self._curSelectInd = 1
            self:RefreshLoopList()

            KTool.SetActive(self.FontStyleButton, true)
            KTool.SetActive(self.FontStyleButton2, true)

            KTool.SetActive(self.BtnSelectAll, false)
        end)
    end
end

--刷新列表
function UIFishPoolCreelDialog:RefreshLoopList()
    self._allFishData = self:GetAllSortData()
    local isTrue = (#self._allFishData > 0 and checkNumber(self._curSelectType) == SelectType.Single)
    KTool.SetActive(self.ChooseNumberPanel, isTrue)

    if self._isInitList then
        --GameUtils.ReloadData(self.LoopList, table.count(self._allFishData))
        self.LoopList:SetListItemCount(table.count(self._allFishData))
    else
        self.LoopList:InitListView(0, Bind(self, self.OnRefreshIndex))
        self.LoopList:SetListItemCount(table.count(self._allFishData))
        
        --self.LoopList:InitGridView(table.count(self._allFishData), Bind(self, self.OnRefreshIndex))
        self._isInitList = true
    end
end

--排序后的数据
function UIFishPoolCreelDialog:GetAllSortData()
    local t = self._allFishDojoData 
    local returnT = {}

    --有排序数据
    if self._curPlaceData then
        if checkNumber(self._curPlaceData.id) == 0 then
            returnT = t
        else
            for k, v in pairs(t) do
                local vo = FishingUtils.GetFishingSpeciesVo(v.fishId)
                if vo then
                    if checkNumber(vo.pond) == checkNumber(self._curPlaceData.id) then
                        table.insert(returnT, v)
                    end
                end
            end
        end
    else
        returnT = t
    end

    table.sort(returnT, function(a, b)
        local vo1 = GoodsConfMgr:GetInstance():GetGoodsVoById(a.fishId)
        local vo2 = GoodsConfMgr:GetInstance():GetGoodsVoById(b.fishId)
        if not self._curSortRareData then
            return checkNumber(vo1.id) < checkNumber(vo2.id)
        else
            if self._curSortRareData.id == 1 then
                return checkNumber(vo1.quality) < checkNumber(vo2.quality)
            elseif self._curSortRareData.id == 2 then
                return checkNumber(vo1.quality) > checkNumber(vo2.quality)
            elseif self._curSortRareData.id == 0 then
                return checkNumber(vo1.id) < checkNumber(vo2.id)
            end
        end
    end)
    return returnT
end

function UIFishPoolCreelDialog:OnRefreshIndex(go, index, row, column)
    if index < 0 then
        return nil
    end

    --local cell = listView:NewListViewItem("Cell")
    local cell = go
    local data = self._allFishData[index + 1]
    local scr = CfUtils.GetLuaScr(cell, UIFishPoolCreelItemNode)
    if scr then
        scr:Refresh(data, function()
            if self._curSelectType == SelectType.Single then
                self:RefreshCurSelectItemInd(index + 1)
            else
                local ind = self:GetIndInSelectData(data)
                --已选中
                if ind > 0 then
                    table.remove(self._selectBatchIds, ind)
                    scr:RefreshSelectActive(false)
                else
                    if checkNumber(self._curBatchType) == ConstantsFishing.FishBasketType.Make then
                        local isCanMakeBait = FishingUtils.IsCanMakeBait(data.fishId)
                        if not isCanMakeBait then
                            GameUtils.Toast(localize("该鱼种无法制作鱼饵"))
                            return
                        end
                    end
                    table.insert(self._selectBatchIds, data)
                    scr:RefreshSelectActive(true)
                end
                --刷新数据
                local scr = CfUtils.GetLuaScr(self.BatchProductionPanel, UIFishPoolCreelBatchNode)
                if scr then
                    scr:RefreshListData(self._selectBatchIds, data, ind > 0)
                end
            end
        end)

        if self._curSelectType == SelectType.Single then
            if (index + 1) == checkNumber(self._curSelectInd) then
                self:RefreshCurSelectItemInfo()
                scr:RefreshSelectActive(true)
            end
        else
            local ind = self:GetIndInSelectData(data)
            scr:RefreshSelectActive(ind > 0)
        end
    end
    --return cell
end

--是否在选中的批量列表中
function UIFishPoolCreelDialog:GetIndInSelectData(data)
    if not data then
        return 0
    end
    for k, v in pairs(self._selectBatchIds) do
        if (checkNumber(v.fishId) == checkNumber(data.fishId)) and (checkNumber(v.rating) == checkNumber(data.rating)) then
            return k
        end
    end
    return 0
end

--批量制作
function UIFishPoolCreelDialog:OnBatchMake()
    if self._curSelectType == SelectType.Batch then
        return
    end
    
    self._selectBatchIds = {}
    self._curSelectType = SelectType.Batch
    KTool.SetActive(self.ChooseNumberPanel, false)
    KTool.SetActive(self.BatchProductionPanel, true)
    self:RefreshCurBatchInfo(ConstantsFishing.FishBasketType.Make)

    KTool.SetActive(self.FontStyleButton, false)
    KTool.SetActive(self.FontStyleButton2, false)

    self._isMake = true 
    self._isShell = false

    --self._isSelectAll = false
    KTool.SetActive(self.BtnSelectAll, true)
    self:FillBtnSelectAll(true)
end

--批量出售
function UIFishPoolCreelDialog:OnBatchSell()
    if self._curSelectType == SelectType.Batch then
        return
    end

    self._selectBatchIds = {}
    self._curSelectType = SelectType.Batch
    KTool.SetActive(self.ChooseNumberPanel, false)
    KTool.SetActive(self.BatchProductionPanel, true)
    self:RefreshCurBatchInfo(ConstantsFishing.FishBasketType.Sell)

    KTool.SetActive(self.FontStyleButton, false)
    KTool.SetActive(self.FontStyleButton2, false)

    self._isMake = false 
    self._isShell = true

    --self._isSelectAll = false
    KTool.SetActive(self.BtnSelectAll, true)
    self:FillBtnSelectAll(true)
end

function UIFishPoolCreelDialog:OnFishBasketChange()
    self:InitData()
    self._curSelectType = SelectType.Single
    self._curSelectInd = 1
    KTool.SetActive(self.FontStyleButton, true)
    KTool.SetActive(self.FontStyleButton2, true)
    self:FillSelf()

    KTool.SetActive(self.BtnSelectAll, false)
end

function UIFishPoolCreelDialog:Update()
    if Utils.TouchCount() > 0 then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            if self._isShowRareSortType then
                local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.DropDown, position,
                UIModule.RootCanvas.canvas.worldCamera)
                if not isInRect then
                    ---不在区域中
                    self:OnBtnRefreshBtnAlign()
                end
            end

            if self._isShowPlaceSortType then
                local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.DropDown2, position,
                UIModule.RootCanvas.canvas.worldCamera)
                if not isInRect then
                    ---不在区域中
                    self:OnBtnRefreshBtnAlign2()
                end
            end
        end
    end
end

--全选
function UIFishPoolCreelDialog:OnBtnSelectAll()
    --self._isSelectAll = not checkBool(self._isSelectAll)
    self:FillBtnSelectAll()
end

function UIFishPoolCreelDialog:FillBtnSelectAll(isFirst)
    --KTool.SetActive(self.ImgHook, checkBool(self._isSelectAll))

    self:RefreshAllSelectFish(isFirst)
end

--刷新所有选中的鱼
function UIFishPoolCreelDialog:RefreshAllSelectFish(isFirst)
    self._selectBatchIds = {}
    if not isFirst then
        for k, v in pairs(self._allFishData) do
            local isJoin = true
            if self._isMake then
                local vo = FishingUtils.GetFishingSpeciesVo(v.fishId)
                if vo then
                    isJoin = checkNumber(vo.baitMaking) > 0
                end
            end
            if isJoin then
                table.insert(self._selectBatchIds, v)
            end
        end
    end

    local scr = CfUtils.GetLuaScr(self.BatchProductionPanel, UIFishPoolCreelBatchNode)
    if scr then
        scr:RefreshListData(self._selectBatchIds, nil)
    end
    self:RefreshLoopList()
end

function UIFishPoolCreelDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local BehaviourAction = CS.Engine.Lib.BehaviourAction
        local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        if behaviourAction then
            behaviourAction.UpdateAction = Bind(self, self.Update)
            self._behaviourAction = behaviourAction
        end
    end))
    return coWait
end

function UIFishPoolCreelDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self._behaviourAction then
            self._behaviourAction.UpdateAction = nil
            self._behaviourAction = nil
        end
        Events.RemoveListener(Constants.EventNames.FishBasketChange, self.EventFishBasketChange)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFishPoolCreelDialog
